 "지금 현재는 문장을 다 쳐도 아무 일이 일어나지 않아요. 어떤 명령을 하면 디버그(수정)할 수 있을까요?": "voice/ko/18c27a26f044.mp3",
 "지금 현재는 예시문장을 전체 단어로만 읽어서 무슨 말인지 모르겠어요. 내가 커서를 움직여서 한글자씩 읽어주면 좋을 것 같아요. 어떻게 명령해야 할까요?": "voice/ko/1ac875e7a6c3.mp3",
 "지금 현재는 타이핑 한 소리가 나오긴하는데, 그 내용을 맞게 쳤는지 틀리게 쳤는지 알 수가 없어요. 어떤 명령을 하면 디버그(수정)할 수 있을까요?": "voice/ko/8431e6e3cde5.mp3",
 "지금 현재는 타이핑을 해도 아무소리가 안나요. 어떻게 명령하면 타이핑소리를 듣게 디버깅(버그 수정, 잘못된 내용 수정)할 수 있을까요?": "voice/ko/52bd28dc337b.mp3",
 "지금까지 쓴 글자 읽기": "voice/ko/bc5da448788e.mp3",
 "지금까지 친 글자예요": "voice/ko/f422aa59b1c2.mp3",
 "지금까지 친 글자예요.": "voice/ko/a2e386954bdd.mp3",
